/// Every interface text of the apps and the console in German (default) and English.
///
/// - [AppLocalizations]: the messages, generated by `flutter gen-l10n` from
///   `lib/l10n/app_en.arb` (template) and `lib/l10n/app_de.arb`.
/// - [problemText]: the text of a server problem code with a generic fallback.
/// - [L10nFormat]: numbers, money, durations and times per locale.
/// - [resolveAppLocale]: the language the app shows.
/// - [termTable]: the fixed German and English terms of docs/spec/01-product.md section 9.
///
/// The package README describes how to add a text and the gates that check it.
library;

export 'src/formatting.dart';
export 'src/generated/app_localizations.dart';
export 'src/locale_resolution.dart';
export 'src/problem_text.dart';
export 'src/term_pair.dart';
export 'src/term_table.dart';
